const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

// Only process PCS_TIMEOUTS_EXT (0x66B97Ax)
if ((canId & 0xFFFFFFF0) !== 0x66B97A0) {
    return null;
}

// Helper function to get bit value
function getBit(buf, bitIndex) {
    const byteIndex = Math.floor(bitIndex / 8);
    const bitOffset = bitIndex % 8;
    if (byteIndex >= buf.length) return false;
    return ((buf[byteIndex] >> bitOffset) & 0x01) === 1;
}

let state = {
    kind: "PcsTimeoutsState",
    version: 1,
    timestampUtc: new Date().toISOString(),

    // Byte 0 (Bit 0-7)
    // All: 1 bit, Unsigned, Factor: 1, Offset: 0
    pcs_dcOcProtTout: getBit(data, 0),           // Bit 0 - DC Over Current Protection Timeout
    pcs_acOvProtTout: getBit(data, 1),           // Bit 1 - AC Over Voltage Protection Timeout
    pcs_acUvProtTout: getBit(data, 2),           // Bit 2 - AC Under Voltage Protection Timeout
    pcs_acOcProtTout: getBit(data, 3),           // Bit 3 - AC Over Current Protection Timeout
    pcs_modOvertProtTout: getBit(data, 4),       // Bit 4 - Module Over Temperature Protection Timeout
    pcs_ccCvRechgVTout: getBit(data, 5),         // Bit 5 - CC/CV Recharge Voltage Timeout
    pcs_batCvChgVTout: getBit(data, 6),          // Bit 6 - Battery CV Charge Voltage Timeout
    pcs_cvChgMaxTimeTout: getBit(data, 7),       // Bit 7 - CV Charge Max Time Timeout

    // Byte 1 (Bit 8-15)
    pcs_cvToFloatCurrTout: getBit(data, 8),      // Bit 8 - CV to Float Current Timeout
    pcs_floatChgVTout: getBit(data, 9),          // Bit 9 - Float Charge Voltage Timeout
    pcs_floatToCcCurrTout: getBit(data, 10),     // Bit 10 - Float to CC Current Timeout
    pcs_pwrOnOffCmdTout: getBit(data, 11),       // Bit 11 - Power ON/OFF Command Timeout
    pcs_faultResetCmdTout: getBit(data, 12),     // Bit 12 - Fault Reset Command Timeout
    pcs_cureParamCmdTout: getBit(data, 13),      // Bit 13 - Cure Param Command Timeout
    pcs_chgResetCmdTout: getBit(data, 14),       // Bit 14 - Charge Reset Command Timeout
    pcs_safetyOneKeyTout: getBit(data, 15),      // Bit 15 - Safety One Key Timeout

    // Byte 2 (Bit 16-23)
    pcs_reMbAddrTout: getBit(data, 16),          // Bit 16 - RE Modbus Address Timeout
    pcs_reMbBaudTout: getBit(data, 17),          // Bit 17 - RE Modbus Baud Timeout
    pcs_hmiMbAddrTout: getBit(data, 18),         // Bit 18 - HMI Modbus Address Timeout
    pcs_hmiMbBaudTout: getBit(data, 19),         // Bit 19 - HMI Modbus Baud Timeout
    pcs_emsCommFailTout: getBit(data, 20),       // Bit 20 - EMS Communication Fail Timeout
    pcs_setPcsPcCmdTimeTout: getBit(data, 21),   // Bit 21 - Set PCS PC Command Time Timeout
    pcs_fault: getBit(data, 22),                 // Bit 22 - PCS Fault
    pcs_rs485Fault: getBit(data, 23),            // Bit 23 - PCS RS485 Fault

    // Byte 3 (Bit 24-25)
    pcs_varPowerTimeout: getBit(data, 24),       // Bit 24 - VAR Power Timeout
    pcs_msg1_2Timeout: getBit(data, 25)          // Bit 25 - PCS MSG1_2 Timeout
};

// ==================== Derived Fields ====================
const allTimeoutFlags = [
    'pcs_dcOcProtTout', 'pcs_acOvProtTout', 'pcs_acUvProtTout', 'pcs_acOcProtTout',
    'pcs_modOvertProtTout', 'pcs_ccCvRechgVTout', 'pcs_batCvChgVTout', 'pcs_cvChgMaxTimeTout',
    'pcs_cvToFloatCurrTout', 'pcs_floatChgVTout', 'pcs_floatToCcCurrTout', 'pcs_pwrOnOffCmdTout',
    'pcs_faultResetCmdTout', 'pcs_cureParamCmdTout', 'pcs_chgResetCmdTout', 'pcs_safetyOneKeyTout',
    'pcs_reMbAddrTout', 'pcs_reMbBaudTout', 'pcs_hmiMbAddrTout', 'pcs_hmiMbBaudTout',
    'pcs_emsCommFailTout', 'pcs_setPcsPcCmdTimeTout', 'pcs_fault', 'pcs_rs485Fault',
    'pcs_varPowerTimeout', 'pcs_msg1_2Timeout'
];

let activeTimeouts = [];
allTimeoutFlags.forEach(flag => {
    if (state[flag] === true) activeTimeouts.push(flag);
});

state.pcs_hasTimeout = activeTimeouts.length > 0;
state.pcs_activeTimeouts = activeTimeouts;
state.pcs_activeTimeoutCount = activeTimeouts.length;

flow.set("pcsTimeoutsState", state);
msg.payload = state;
return msg;

var state = flow.get("pcsTimeoutsState");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;
